/* Modern CSS Scroll-Driven Parallax */
@keyframes parallaxMove {
  from { transform: translateY(15%); }
  to { transform: translateY(-15%); }
}

.parallax-container {
  position: relative;
  overflow: hidden;
}

.parallax-media {
  animation: parallaxMove linear both;
  animation-timeline: view();
  animation-range: entry 0% exit 100%;
}
